# When both have pre-release versions:
# Compare each dot separated identifier from left to right until a difference is found:
# 1. Identifiers consisting of only digits are compared numerically.
# 2. Identifiers with letters or hyphens are compared lexically in ASCII sort order.
# 3. Numeric identifiers always have lower precedence than non-numeric identifiers.
# 4. A larger set of pre-release fields has a higher precedence than a smaller set,
#    if all of the preceding identifiers are equal.
for a, b in zip(self.prerelease, other.prerelease):
    if a == b:
        continue
    is_a_int = isinstance(a, int)
    is_b_int = isinstance(b, int)
    if is_a_int and is_b_int:
        return a < b
    elif is_a_int and not is_b_int:
        # Numeric has lower precedence than non-numeric
        return True
    elif not is_a_int and is_b_int:
        # Non-numeric has higher precedence than numeric
        return False
    else:
        # Both non-numeric, lexical ASCII sort order
        return str(a) < str(b)

return len(self.prerelease) < len(other.prerelease)

